$ErrorActionPreference = 'Stop'
$src = 'C:\Users\Cung Đức Lương\Downloads\kiên thức cf + luật.docx'

$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0
$doc = $word.Documents.Open($src)

try {
    # rename the three shouty headings
    $rename = @{
        ("CH" + [char]0x1EC8 + " TI" + [char]0xCA + "U:") = ("Ch" + [char]0x1EC9 + " ti" + [char]0xEA + "u ch" + [char]0x1EA5 + "t l" + [char]0x1B0 + [char]0x1EE3 + "ng")
        ("TR" + [char]0xCA + "N T" + [char]0x1ED4 + "NG THANG 100 " + [char]0x110 + [char]0x1EC2 + "M:") = ("Ph" + [char]0xE2 + "n m" + [char]0x1EE9 + "c theo thang 100 " + [char]0x111 + [char]0x1EC3 + "m")
        ("C" + [char]0xC1 + "C T" + [char]0x1EEA + " KH" + [char]0xD3 + "A:") = ("C" + [char]0xE1 + "c t" + [char]0x1EEB + " kh" + [char]0xF3 + "a c" + [char]0x1EA7 + "n bi" + [char]0x1EBF + "t")
    }

    $renamed = 0
    $colons = 0
    foreach ($p in $doc.Paragraphs) {
        $lvl = $p.OutlineLevel
        if ($lvl -lt 1 -or $lvl -gt 3) { continue }
        $r = $p.Range.Duplicate
        $r.MoveEnd(1, -1) | Out-Null
        $t = $r.Text
        if ($null -eq $t) { continue }
        $t = $t.TrimEnd()
        if ($t -eq '') { continue }

        if ($rename.ContainsKey($t)) {
            $r.Text = $rename[$t]
            $renamed++
            continue
        }
        if ($t.EndsWith(':')) {
            $r.Text = $t.Substring(0, $t.Length - 1)
            $colons++
        }
    }
    Write-Output ("headings renamed: $renamed ; trailing colons removed: $colons")

    if ($doc.TablesOfContents.Count -gt 0) { $doc.TablesOfContents.Item(1).Update() }

    $doc.Save()
    Write-Output "CLEANUP SAVED OK"
}
finally {
    $doc.Close(0)
    $word.Quit()
}

